  "",
  "        <div class=\"field\">",
  "          <label for=\"hook\">오프닝 후킹 문장</label>",
  "          <textarea class=\"textarea\" id=\"hook\" style=\"min-height:78px\">직업이 사라지는 것이 아니라, 반복 업무가 먼저 바뀝니다.</textarea>",
