  "      state.scenes.splice(state.selected, 1); state.selected = Math.min(state.selected, state.scenes.length - 1); state.currentMs = getTimings()[state.selected].start; renderSceneList(); loadSelectedScene(); updateTimeline(); renderFrame(); showToast('선택 장면을 삭제했습니다.');",
  "    }",
  "",
  "    function getPalette() {",
  "      const accent = ui.accent.value;",
  "      const sub = ui.sub.value;",
  "      const palettes = {",
  "        ranking: { top: '#0b0d12', bottom: '#030405', surface: '#14171e', text: '#ffffff', muted: '#a6adba', accent, sub, light: false },",
  "        brief: { top: '#071427', bottom: '#020710', surface: '#10284a', text: '#f7fbff', muted: '#9db1c9', accent, sub, light: false },",
  "        news: { top: '#15151a', bottom: '#07070a', surface: '#25252c', text: '#ffffff', muted: '#b7b7c0', accent, sub, light: false },",
  "        clean: { top: '#f7f9fc', bottom: '#e7edf5', surface: '#ffffff', text: '#101828', muted: '#526177', accent, sub, light: true }",
  "      };",
  "      const palette = { ...(palettes[ui.template.value] || palettes.ranking) };",
  "      if (getBackgroundPreset().light) {",
