  "        ctx.fillStyle = base; ctx.fillRect(0, 0, width, height);",
  "        ctx.save(); ctx.strokeStyle = 'rgba(74,233,218,.24)'; ctx.lineWidth = 2;",
  "        const horizon = 660;",
  "        for (let x = -360; x <= width + 360; x += 120) {",
