  "        }",
  "        ctx.restore();",
  "      } else if (preset.design === 'red') {",
  "        ctx.fillStyle = '#060509'; ctx.fillRect(0, 0, width, height);",
  "        const glow = ctx.createRadialGradient(900 - progress * 90, 440, 10, 860, 540, 850);",
  "        glow.addColorStop(0, 'rgba(255,58,87,.62)'); glow.addColorStop(.52, 'rgba(118,12,35,.24)'); glow.addColorStop(1, 'rgba(0,0,0,0)');",
  "        ctx.fillStyle = glow; ctx.fillRect(0, 0, width, height);",
