  "        ctx.translate(740, 1450); ctx.rotate(-.2); ctx.fillRect(0, 0, 520, 22); ctx.fillRect(-110, 70, 690, 5); ctx.restore();",
  "      } else if (preset.design === 'flow') {",
  "        const base = ctx.createLinearGradient(0, 0, width, height);",
  "        base.addColorStop(0, '#020817'); base.addColorStop(.6, '#063d79'); base.addColorStop(1, '#0a8399');",
  "        ctx.fillStyle = base; ctx.fillRect(0, 0, width, height);",
  "        ctx.save(); ctx.lineWidth = 9; ctx.lineCap = 'round';",
  "        for (let index = 0; index < 8; index += 1) {",
