  "          ctx.stroke();",
  "        }",
  "        ctx.restore();",
  "      } else if (preset.design === 'sunset') {",
  "        const base = ctx.createLinearGradient(0, 0, width, height);",
  "        base.addColorStop(0, '#17123c'); base.addColorStop(.55, '#6c285f'); base.addColorStop(1, '#ef6d53');",
  "        ctx.fillStyle = base; ctx.fillRect(0, 0, width, height);",
  "        ctx.fillStyle = `rgba(255,201,90,${.2 + progress * .12})`; ctx.beginPath(); ctx.arc(820, 420, 260 + progress * 70, 0, Math.PI * 2); ctx.fill();",
  "      } else if (preset.design === 'matrix') {",
  "        ctx.fillStyle = '#031712'; ctx.fillRect(0, 0, width, height); ctx.font = '700 26px monospace'; ctx.fillStyle = 'rgba(126,255,199,.25)';",
  "        for (let column = 0; column < 18; column += 1) { for (let row = 0; row < 30; row += 1) { const y = ((row * 84 + progress * 420) % 2200) - 120; ctx.fillText(String((column * 7 + row) % 10), 48 + column * 62, y); } }",
  "      } else if (preset.design === 'orbit') {",
  "        const base = ctx.createLinearGradient(0, 0, width, height); base.addColorStop(0, '#07132e'); base.addColorStop(1, '#162d62'); ctx.fillStyle = base; ctx.fillRect(0, 0, width, height);",
  "        ctx.save(); ctx.translate(720, 860); ctx.rotate(progress * .9); ctx.strokeStyle = 'rgba(72,230,218,.52)'; ctx.lineWidth = 16; for (let ring = 0; ring < 5; ring += 1) { ctx.beginPath(); ctx.ellipse(0, 0, 170 + ring * 82, 58 + ring * 26, ring * .2, 0, Math.PI * 2); ctx.stroke(); } ctx.restore();",
  "      } else if (preset.design === 'pulse') {",
  "        const base = ctx.createLinearGradient(0, 0, width, height); base.addColorStop(0, '#140a2e'); base.addColorStop(.6, '#502080'); base.addColorStop(1, '#c43c8f'); ctx.fillStyle = base; ctx.fillRect(0, 0, width, height);",
  "        ctx.save(); ctx.strokeStyle = 'rgba(255,209,248,.38)'; ctx.lineWidth = 6; ctx.beginPath(); for (let x = -30; x <= width + 30; x += 12) { const y = 980 + Math.sin(x / 80 + progress * 7) * 150; x === -30 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); } ctx.stroke(); ctx.restore();",
  "      } else if (preset.design === 'slate') {",
  "        const base = ctx.createLinearGradient(0, 0, width, height); base.addColorStop(0, '#152131'); base.addColorStop(.6, '#49657e'); base.addColorStop(1, '#d0e4f4'); ctx.fillStyle = base; ctx.fillRect(0, 0, width, height);",
  "        ctx.save(); ctx.globalAlpha = .2; ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 3; for (let index = -2; index < 10; index += 1) { ctx.beginPath(); ctx.moveTo(index * 180 + progress * 180, 0); ctx.lineTo(index * 180 - 420 + progress * 180, height); ctx.stroke(); } ctx.restore();",
  "      } else {",
