  "",
  "    function drawBackground(palette, progress) {",
  "      const action = state.backgroundAction || 'none';",
  "      if (action === 'none') { drawBackgroundLayer(palette, progress); return; }",
  "      ctx.fillStyle = '#03050a'; ctx.fillRect(0, 0, canvas.width, canvas.height);",
