  "    ui.newProject.addEventListener('click', () => { state.projectId = null; closeOverlay(ui.projectsOverlay); showToast('새 프로젝트로 시작합니다. 현재 내용은 그대로 유지됩니다.'); });",
  "    ui.adminButton.addEventListener('click', () => { if (state.adminPassword) { openOverlay(ui.adminOverlay); fetchAdminOverview().catch(error => showToast(error.message || '관리자 현황을 불러오지 못했습니다.')); } else { openOverlay(ui.adminLoginOverlay); ui.adminPassword.focus(); } });",
  "    ui.adminLogin.addEventListener('click', submitAdminLogin);",
  "    ui.adminPassword.addEventListener('keydown', event => { if (event.key === 'Enter') submitAdminLogin(); });",
  "    ui.backgroundAction.addEventListener('change', () => { state.backgroundAction = ui.backgroundAction.value; renderFrame(); });",
  "    ui.backgroundType.addEventListener('change', renderBackgroundGallery);",
  "    ui.homeBrand.addEventListener('click', () => { window.location.href = '/'; }); ui.homeBrand.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); window.location.href = '/'; } });",
  "    document.querySelectorAll('[data-close-overlay]').forEach(button => button.addEventListener('click', () => closeOverlay(document.getElementById(button.dataset.closeOverlay))));",
  "    [ui.projectsOverlay, ui.adminLoginOverlay, ui.adminOverlay].forEach(overlay => overlay.addEventListener('click', event => { if (event.target === overlay) closeOverlay(overlay); }));",
  "",
  "    ui.timeline.addEventListener('input', event => {",
  "      stopPlayback();",
  "      state.currentMs = Number(event.target.value);",
  "      updateTimeline();",
  "      renderFrame();",
  "    });",
  "",
  "    [ui.template, ui.accent, ui.sub].forEach(element => element.addEventListener('input', () => {",
  "      document.documentElement.style.setProperty('--accent', ui.accent.value);",
  "      document.documentElement.style.setProperty('--accent-2', ui.sub.value);",
