const BACKGROUND_ASSETS = {"/assets/backgrounds/ai-tech.webp":"","/assets/backgrounds/business-growth.webp":"","/assets/backgrounds/local-tourism.webp":"","/assets/backgrounds/startup-rnd.webp":"","/assets/backgrounds/global-news.webp":"","/assets/brand/mentork-logo.webp":""};

const JSON_HEADERS = {
  "content-type": "application/json; charset=utf-8",
  "cache-control": "no-store",
};

function jsonResponse(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...JSON_HEADERS, ...extraHeaders },
  });
}

function outputText(payload) {
  if (typeof payload.output_text === "string") return payload.output_text;
  for (const item of payload.output || []) {
    for (const content of item.content || []) {
      if (content.type === "output_text" && typeof content.text === "string") return content.text;
    }
  }
  return "";
}

function cleanText(value, max) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  return text.slice(0, max);
}

function normalizeDraft(value, pointCount) {
  if (!value || !Array.isArray(value.points)) throw new Error("invalid_draft");
  const points = value.points
    .slice(0, pointCount)
    .map((point) => ({
      title: cleanText(point && point.title, 32),
      subtitle: cleanText(point && point.subtitle, 82),
    }))
    .filter((point) => point.title && point.subtitle);
  if (points.length < Math.min(4, pointCount)) throw new Error("insufficient_points");
  return {
    hook: cleanText(value.hook, 120),
    points,
    conclusion: cleanText(value.conclusion, 100),
    cta: cleanText(value.cta, 70),
  };
}

async function generateContent(request, env) {
  if (!env.OPENAI_API_KEY) {
    return jsonResponse({
      code: "API_KEY_MISSING",
      error: "AI API 키 연결이 아직 필요합니다.",
    }, 503);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ error: "요청 형식이 올바르지 않습니다." }, 400);
  }

  const topic = cleanText(body.topic, 90);
  const template = cleanText(body.template, 30) || "핵심 브리핑";
  const duration = Math.min(60, Math.max(15, Number(body.duration) || 20));
  const pointCount = Math.min(8, Math.max(4, Number(body.pointCount) || 5));
  if (topic.length < 2) return jsonResponse({ error: "제목이나 주제를 입력해 주세요." }, 400);

  const instructions = [
    "당신은 한국어 세로형 숏폼 콘텐츠 전문 기획자다.",
    "주어진 제목을 바탕으로 사실을 과장하거나 출처 없는 수치를 만들지 말고, 짧고 명확한 영상 초안을 작성한다.",
    "hook은 첫 3초 안에 문제·반전·이득 중 하나를 선명하게 약속하는 한 문장, points는 1.2~2.2초 컷으로 나눌 수 있는 서로 중복되지 않는 핵심 장면, conclusion은 첫 장면과 연결되는 통찰, cta는 저장·댓글·공유 중 하나를 요청하는 부담 없는 행동 유도 문장으로 쓴다.",
    "각 point.title은 18자 안팎의 강한 핵심 문장, subtitle은 45자 안팎의 구체적 설명으로 작성한다.",
    "어려운 외래어와 추상적 표현을 줄이고 한국어 맞춤법을 지킨다. 느린 인사말·로고 인트로·배경 설명은 쓰지 않는다.",
  ].join(" ");

  const userPrompt = [
    "제목: " + topic,
    "영상 길이: " + duration + "초",
    "화면 템플릿: " + template,
    "핵심 장면 수: " + pointCount + "개",
    "대상: 일반 시청자",
  ].join("\n");

  const apiResponse = await fetch("https://api.openai.com/v1/responses", {
    method: "POST",
    headers: {
      "authorization": "Bearer " + env.OPENAI_API_KEY,
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: env.OPENAI_MODEL || "gpt-5-mini",
      store: false,
      input: [
        { role: "system", content: instructions },
        { role: "user", content: userPrompt },
      ],
      text: {
        format: {
          type: "json_schema",
          name: "motion_short_draft",
          strict: true,
          schema: {
            type: "object",
            properties: {
              hook: { type: "string" },
              points: {
                type: "array",
                minItems: pointCount,
                maxItems: pointCount,
                items: {
                  type: "object",
                  properties: {
                    title: { type: "string" },
                    subtitle: { type: "string" },
                  },
                  required: ["title", "subtitle"],
                  additionalProperties: false,
                },
              },
              conclusion: { type: "string" },
              cta: { type: "string" },
            },
            required: ["hook", "points", "conclusion", "cta"],
            additionalProperties: false,
          },
        },
      },
      max_output_tokens: 1600,
    }),
  });

  if (!apiResponse.ok) {
    return jsonResponse({
      error: apiResponse.status === 429
        ? "AI 사용량이 잠시 많습니다. 잠시 후 다시 시도해 주세요."
        : "AI 서비스 응답을 처리하지 못했습니다.",
    }, apiResponse.status === 429 ? 429 : 502);
  }

  try {
    const payload = await apiResponse.json();
    const text = outputText(payload);
    if (!text) throw new Error("empty_output");
    return jsonResponse(normalizeDraft(JSON.parse(text), pointCount));
  } catch {
    return jsonResponse({ error: "AI 초안 형식을 확인하지 못했습니다. 다시 생성해 주세요." }, 502);
  }
}

function ownerKey(request) {
  return request.headers.get("oai-authenticated-user-id")
    || request.headers.get("oai-authenticated-user-email")
    || "site-owner";
}

function adminAuthorized(request, env) {
  const expected = String(env.MOTION_ADMIN_PASSWORD || "");
  const supplied = String(request.headers.get("x-admin-password") || "");
  return Boolean(expected && supplied && supplied === expected);
}

function databaseUnavailable() {
  return jsonResponse({ ok: false, error: "프로젝트 저장 데이터베이스가 연결되지 않았습니다." }, 503);
}

async function trackEvent(request, env) {
  if (!env.DB) return databaseUnavailable();
  let body = {};
  try { body = await request.json(); } catch { body = {}; }
  const type = cleanText(body.type, 40);
  if (!type) return jsonResponse({ ok: false, error: "이벤트 유형이 필요합니다." }, 400);
  const now = new Date().toISOString();
  await env.DB.prepare("INSERT INTO motion_events(owner_key,project_id,event_type,detail_json,created_at) VALUES(?,?,?,?,?)")
    .bind(ownerKey(request), cleanText(body.projectId, 100) || null, type, JSON.stringify(body.detail || {}), now).run();
  return jsonResponse({ ok: true });
}

async function listProjects(request, env) {
  if (!env.DB) return databaseUnavailable();
  const rows = await env.DB.prepare("SELECT id,title,payload_json,archived,created_at,updated_at,last_opened_at FROM motion_projects WHERE owner_key=? ORDER BY archived ASC, updated_at DESC")
    .bind(ownerKey(request)).all();
  return jsonResponse({ ok: true, projects: (rows.results || []).map(row => ({ ...row, payload: JSON.parse(row.payload_json || "{}") })) });
}

async function readProject(request, env, id) {
  if (!env.DB) return databaseUnavailable();
  const key = ownerKey(request);
  const row = await env.DB.prepare("SELECT id,title,payload_json,archived,created_at,updated_at,last_opened_at FROM motion_projects WHERE id=? AND owner_key=?")
    .bind(id, key).first();
  if (!row) return jsonResponse({ ok: false, error: "프로젝트를 찾지 못했습니다." }, 404);
  const now = new Date().toISOString();
  await env.DB.prepare("UPDATE motion_projects SET last_opened_at=? WHERE id=? AND owner_key=?").bind(now, id, key).run();
  await env.DB.prepare("INSERT INTO motion_events(owner_key,project_id,event_type,detail_json,created_at) VALUES(?,?,?,?,?)")
    .bind(key, id, "project_loaded", JSON.stringify({}), now).run();
  return jsonResponse({ ok: true, project: { ...row, payload: JSON.parse(row.payload_json || "{}") } });
}

async function saveProject(request, env) {
  if (!env.DB) return databaseUnavailable();
  let body;
  try { body = await request.json(); } catch { return jsonResponse({ ok: false, error: "저장할 프로젝트 형식이 올바르지 않습니다." }, 400); }
  const input = body && body.project ? body.project : body;
  const title = cleanText(input && input.title, 90) || "제목 없는 모션 프로젝트";
  const payload = input && input.payload;
  if (!payload || typeof payload !== "object") return jsonResponse({ ok: false, error: "프로젝트 내용이 없습니다." }, 400);
  const key = ownerKey(request);
  const id = cleanText(input.id, 100) || crypto.randomUUID();
  const now = new Date().toISOString();
  const existing = await env.DB.prepare("SELECT owner_key FROM motion_projects WHERE id=?").bind(id).first();
  if (existing && existing.owner_key !== key) return jsonResponse({ ok: false, error: "접근할 수 없는 프로젝트입니다." }, 403);
  if (existing) {
    await env.DB.prepare("UPDATE motion_projects SET title=?,payload_json=?,updated_at=?,archived=0 WHERE id=? AND owner_key=?")
      .bind(title, JSON.stringify(payload), now, id, key).run();
  } else {
    await env.DB.prepare("INSERT INTO motion_projects(id,owner_key,title,payload_json,archived,created_at,updated_at,last_opened_at) VALUES(?,?,?,?,?,?,?,?)")
      .bind(id, key, title, JSON.stringify(payload), 0, now, now, now).run();
  }
  await env.DB.prepare("INSERT INTO motion_events(owner_key,project_id,event_type,detail_json,created_at) VALUES(?,?,?,?,?)")
    .bind(key, id, "project_saved", JSON.stringify({ title }), now).run();
  return jsonResponse({ ok: true, id, updatedAt: now });
}

async function adminOverview(request, env) {
  if (!adminAuthorized(request, env)) return jsonResponse({ ok: false, error: "관리자 비밀번호가 올바르지 않습니다." }, 401);
  if (!env.DB) return databaseUnavailable();
  const key = ownerKey(request);
  const [projects, events, stats] = await Promise.all([
    env.DB.prepare("SELECT id,title,archived,created_at,updated_at,last_opened_at FROM motion_projects WHERE owner_key=? ORDER BY updated_at DESC").bind(key).all(),
    env.DB.prepare("SELECT event_type,project_id,detail_json,created_at FROM motion_events WHERE owner_key=? ORDER BY created_at DESC LIMIT 40").bind(key).all(),
    env.DB.prepare("SELECT COUNT(*) total_projects, COALESCE(SUM(CASE WHEN archived=0 THEN 1 ELSE 0 END),0) active_projects, COALESCE(SUM(CASE WHEN archived=1 THEN 1 ELSE 0 END),0) archived_projects FROM motion_projects WHERE owner_key=?").bind(key).first(),
  ]);
  const counts = await env.DB.prepare("SELECT event_type,COUNT(*) count FROM motion_events WHERE owner_key=? GROUP BY event_type").bind(key).all();
  return jsonResponse({ ok: true, stats: { ...(stats || {}), events: Object.fromEntries((counts.results || []).map(row => [row.event_type, Number(row.count || 0)])) }, projects: projects.results || [], events: events.results || [] });
}

async function archiveProject(request, env, id) {
  if (!adminAuthorized(request, env)) return jsonResponse({ ok: false, error: "관리자 비밀번호가 올바르지 않습니다." }, 401);
  if (!env.DB) return databaseUnavailable();
  let body = {};
  try { body = await request.json(); } catch { body = {}; }
  const archived = body.archived ? 1 : 0;
  const key = ownerKey(request);
  const now = new Date().toISOString();
  const result = await env.DB.prepare("UPDATE motion_projects SET archived=?,updated_at=? WHERE id=? AND owner_key=?").bind(archived, now, id, key).run();
  if (!result.meta || !result.meta.changes) return jsonResponse({ ok: false, error: "프로젝트를 찾지 못했습니다." }, 404);
  await env.DB.prepare("INSERT INTO motion_events(owner_key,project_id,event_type,detail_json,created_at) VALUES(?,?,?,?,?)")
    .bind(key, id, archived ? "project_archived" : "project_restored", JSON.stringify({}), now).run();
  return jsonResponse({ ok: true, archived: Boolean(archived) });
}

export default {
  async fetch(request, env, ctx) {
    void ctx;
    const url = new URL(request.url);

    const encodedAsset = BACKGROUND_ASSETS[url.pathname];
    if (encodedAsset) {
      const binary = atob(encodedAsset);
      const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
      return new Response(bytes, {
        headers: {
          "content-type": "image/webp",
          "cache-control": "public, max-age=31536000, immutable",
          "x-content-type-options": "nosniff",
        },
      });
    }

    if (url.pathname === "/api/generate-content") {
      if (request.method !== "POST") {
        return jsonResponse({ error: "POST 요청만 지원합니다." }, 405, { allow: "POST" });
      }
      try {
        return await generateContent(request, env);
      } catch {
        return jsonResponse({ error: "AI 콘텐츠 생성 중 연결 오류가 발생했습니다." }, 502);
      }
    }

    if (url.pathname === "/api/track" && request.method === "POST") {
      try { return await trackEvent(request, env); } catch { return jsonResponse({ ok: false }, 500); }
    }

    if (url.pathname === "/api/projects" && request.method === "GET") {
      try { return await listProjects(request, env); } catch { return jsonResponse({ ok: false, error: "프로젝트 목록을 불러오지 못했습니다." }, 500); }
    }

    if (url.pathname === "/api/projects" && request.method === "POST") {
      try { return await saveProject(request, env); } catch { return jsonResponse({ ok: false, error: "프로젝트를 저장하지 못했습니다." }, 500); }
    }

    if (url.pathname.startsWith("/api/projects/") && request.method === "GET") {
      try { return await readProject(request, env, decodeURIComponent(url.pathname.split("/").pop())); } catch { return jsonResponse({ ok: false, error: "프로젝트를 불러오지 못했습니다." }, 500); }
    }

    if (url.pathname === "/api/admin/overview" && request.method === "GET") {
      try { return await adminOverview(request, env); } catch { return jsonResponse({ ok: false, error: "관리자 현황을 불러오지 못했습니다." }, 500); }
    }

    if (url.pathname.startsWith("/api/admin/projects/") && url.pathname.endsWith("/archive") && request.method === "POST") {
      try { return await archiveProject(request, env, decodeURIComponent(url.pathname.split("/")[4])); } catch { return jsonResponse({ ok: false, error: "보관 상태를 변경하지 못했습니다." }, 500); }
    }

    if (url.pathname === "/health") return jsonResponse({ ok: true });
    if (url.pathname !== "/") return new Response("Not found", { status: 404 });

    return new Response(page, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
        "content-security-policy": "default-src 'self'; img-src 'self' data: blob:; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self' https://api.openai.com; base-uri 'none'; frame-ancestors 'self'",
        "referrer-policy": "no-referrer",
        "x-content-type-options": "nosniff",
      },
    });
  },
};
